import unicodedata


def canonical(key):
    """Return the canonical form of *key*.

    Keys are compared case-insensitively using Unicode casefolding after
    NFC normalization, so any two spellings that are equivalent under those
    rules map to the same canonical string.
    """
    return unicodedata.normalize("NFC", key).casefold()
EOF
